import json
# 7x7 tile coloring inferred from demo: connect equal-color markers along tile rows/columns;
# intersections of color-2 and color-3 strokes are color 6.
tile = [[0]*7 for _ in range(7)]
for r in range(6): tile[r][2] = 3
for r in (1,3):
    for c in range(5): tile[r][c] = 2
    tile[r][2] = 6
out=[]
for tr in range(7):
    for ir in range(4):
        row=[]
        for tc in range(7):
            if tc: row.append(8)
            row.extend([tile[tr][tc]]*4)
        out.append(row)
    if tr<6: out.append([8]*28)
assert len(out)==28 and all(len(row)==28 for row in out)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

